-- Step 1 of 4: add accounts.region as NULLABLE, no default.
-- Postgres: ADD COLUMN with no default is a catalog-only change (no table rewrite, no scan),
-- but it still needs a brief ACCESS EXCLUSIVE lock. lock_timeout makes it give up instead of
-- queueing every write on accounts behind a long-running transaction; retry on failure.
-- Reversible: yes (see .down.sql). Safe to run twice (IF NOT EXISTS).
SET lock_timeout = '3s';

ALTER TABLE accounts ADD COLUMN IF NOT EXISTS region text;

COMMENT ON COLUMN accounts.region IS
  'Account region code. NOT NULL is enforced in steps 3-4 once the backfill is done. Not personal data.';

-- Rejected-rows table for the backfill (step 2): accounts whose region could not be derived.
CREATE TABLE IF NOT EXISTS accounts_region_rejects (
  account_id  bigint      PRIMARY KEY,
  reason      text        NOT NULL,   -- region_underivable | region_blank | region_not_in_set
  seen_value  text,                   -- what derivation produced, if anything
  rejected_at timestamptz NOT NULL DEFAULT now()
);

-- Checkpoint so the batched backfill can be stopped and restarted.
CREATE TABLE IF NOT EXISTS accounts_region_backfill_progress (
  id          smallint    PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  last_id     bigint      NOT NULL DEFAULT 0,
  updated     bigint      NOT NULL DEFAULT 0,
  rejected    bigint      NOT NULL DEFAULT 0,
  updated_at  timestamptz NOT NULL DEFAULT now()
);
INSERT INTO accounts_region_backfill_progress (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

-- Down for step 1. The DROP is destructive once step 2 has filled values, so keep a copy first.
-- The copy table is kept on purpose; it is removed only by hand, with approval (P1).
SET lock_timeout = '3s';

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = 'accounts' AND column_name = 'region') THEN
    CREATE TABLE IF NOT EXISTS accounts_region_backup AS
      SELECT id AS account_id, region FROM accounts WHERE region IS NOT NULL;
  END IF;
END $$;

ALTER TABLE accounts DROP COLUMN IF EXISTS region;
DROP TABLE IF EXISTS accounts_region_backfill_progress;
-- accounts_region_rejects is kept: it is the record of rows the backfill could not fill.

-- Step 3 of 4: enforce "region IS NOT NULL" for new writes, then prove it for old rows,
-- without a long lock.
--  * ADD CONSTRAINT ... NOT VALID: brief lock, no scan; new and updated rows are checked from now on.
--  * VALIDATE CONSTRAINT: scans the 40M rows under SHARE UPDATE EXCLUSIVE, which does NOT block
--    reads or writes. Run it as its own transaction.
-- Gate: only run when accounts has 0 NULL regions and accounts_region_rejects is resolved;
-- otherwise VALIDATE fails (safely, nothing changes).
-- Reversible: yes. Safe to run twice.
SET lock_timeout = '3s';

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'accounts_region_not_null') THEN
    ALTER TABLE accounts ADD CONSTRAINT accounts_region_not_null CHECK (region IS NOT NULL) NOT VALID;
  END IF;
END $$;

-- separate statement / transaction:
ALTER TABLE accounts VALIDATE CONSTRAINT accounts_region_not_null;

-- Down for step 3: drop the check. No data changes.
SET lock_timeout = '3s';
ALTER TABLE accounts DROP CONSTRAINT IF EXISTS accounts_region_not_null;

-- Step 4 of 4: make it a real column-level NOT NULL (what the ticket asks for).
-- Postgres 12+: SET NOT NULL skips the full-table scan when a VALIDATED CHECK (region IS NOT NULL)
-- exists, so this is a brief lock only. On Postgres < 12 it would scan 40M rows under
-- ACCESS EXCLUSIVE: do NOT run this step there; keep the validated check from step 3 instead.
-- Then the now-redundant check is dropped.
-- Reversible: yes. Safe to run twice.
SET lock_timeout = '3s';

ALTER TABLE accounts ALTER COLUMN region SET NOT NULL;
ALTER TABLE accounts DROP CONSTRAINT IF EXISTS accounts_region_not_null;

-- Down for step 4: relax to nullable, and restore step 3's state (a validated check).
-- ADD ... NOT VALID then VALIDATE keeps the lock short.
SET lock_timeout = '3s';
ALTER TABLE accounts ALTER COLUMN region DROP NOT NULL;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'accounts_region_not_null') THEN
    ALTER TABLE accounts ADD CONSTRAINT accounts_region_not_null CHECK (region IS NOT NULL) NOT VALID;
  END IF;
END $$;
ALTER TABLE accounts VALIDATE CONSTRAINT accounts_region_not_null;
